    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c >= 0 && c <= 127) {
            lb = ensureCapacity(lb, 1);
            lb.buffer[lb.offset++] = (byte) c;
        } else if (c <= 2047) {
            lb = ensureCapacity(lb, 2);
            lb.buffer[lb.offset++] = (byte) (192 | (c >> 6));
            lb.buffer[lb.offset++] = (byte) (128 | (c & 0x3F));
        } else {
            lb = ensureCapacity(lb, 3);
            lb.buffer[lb.offset++] = (byte) (224 | (c >> 12));
            lb.buffer[lb.offset++] = (byte) (128 | ((c >> 6) & 0x3F));
            lb.buffer[lb.offset++] = (byte) (128 | (c & 0x3F));
        }
    }
    return lb;
}

