public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder output = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < length) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case 'b':
                        output.append('\b');
                        i++;
                        break;
                    case 't':
                        output.append('\t');
                        i++;
                        break;
                    case 'n':
                        output.append('\n');
                        i++;
                        break;
                    case 'f':
                        output.append('\f');
                        i++;
                        break;
                    case 'r':
                        output.append('\r');
                        i++;
                        break;
                    case '"':
                        output.append('"');
                        i++;
                        break;
                    case '\'':
                        output.append('\'');
                        i++;
                        break;
                    case '\\':
                        output.append('\\');
                        i++;
                        break;
                    case 'u':
                        if (i + 5 < length) {
                            int unicode = Integer.parseInt(str.substring(i + 2, i + 6), 16);
                            output.append((char) unicode);
                            i += 5;
                        } else {
                            throw new Exception("Malformed Unicode escape sequence");
                        }
                        break;
                    default:
                        output.append(c);
                        break;
                }
            } else {
                output.append(c);
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

