final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    int utf8Index = constantPoolEntryIndex * 8 + 1; // Assuming each entry is 8 bytes and index is 1-based
    int length = ((classFileBuffer[utf8Index] & 0xFF) << 8) | (classFileBuffer[utf8Index + 1] & 0xFF);
    int charIndex = 0;
    for (int i = 0; i < length; i++) {
        int currentByte = classFileBuffer[utf8Index + 2 + i] & 0xFF;
        if ((currentByte & 0x80) == 0) {
            // 1-byte format
            charBuffer[charIndex++] = (char) currentByte;
        } else if ((currentByte & 0xE0) == 0xC0) {
            // 2-byte format
            int byte1 = currentByte & 0x1F;
            int byte2 = classFileBuffer[utf8Index + 2 + ++i] & 0x3F;
            charBuffer[charIndex++] = (char) ((byte1 << 6) | byte2);
        } else if ((currentByte & 0xF0) == 0xE0) {
            // 3-byte format
            int byte1 = currentByte & 0x0F;
            int byte2 = classFileBuffer[utf8Index + 2 + ++i] & 0x3F;
            int byte3 = classFileBuffer[utf8Index + 2 + ++i] & 0x3F;
            charBuffer[charIndex++] = (char) ((byte1 << 12) | (byte2 << 6) | byte3);
        }
    }
    return new String(charBuffer, 0, charIndex);
}

