protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();

    if (edgeList.isEmpty()) {
        return new GraphPathImpl<>(graph, null, vertexList, 0.0);
    }

    V startVertex = graph.getEdgeSource(edgeList.get(0));
    vertexList.add(startVertex);

    Set<E> visitedEdges = new HashSet<>();
    E currentEdge = edgeList.get(0);
    visitedEdges.add(currentEdge);

    while (visitedEdges.size() < tour.size()) {
        V currentVertex = graph.getEdgeTarget(currentEdge);
        vertexList.add(currentVertex);

        currentEdge = findNextEdge(currentVertex, visitedEdges, tour, graph);
        visitedEdges.add(currentEdge);
    }

    vertexList.add(graph.getEdgeTarget(currentEdge));

    double weight = 0.0;
    for (E edge : tour) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, startVertex, vertexList, weight);
}

private E findNextEdge(V currentVertex, Set<E> visitedEdges, Set<E> tour, Graph<V,E> graph) {
    for (E edge : tour) {
        if (!visitedEdges.contains(edge)) {
            if (graph.getEdgeSource(edge).equals(currentVertex) || graph.getEdgeTarget(edge).equals(currentVertex)) {
                return edge;
            }
        }
    }
    return null;
}

