        switch (c) {
            case 'B': // byte
            case 'C': // char
            case 'F': // float
            case 'I': // int
            case 'S': // short
            case 'Z': // boolean
                index++; // These take up 1 slot
                break;
            case 'D': // double
            case 'J': // long
                index++; // These take up 2 slots
                break;
            case 'L': // Object reference
                // Find the ';'
                while (descriptor.charAt(index) != ';') {
                    index++;
                }
                index++; // Move past the ';'
                break;
            case '[': // Array
                // Skip over the array dimensions
                while (descriptor.charAt(index) == '[') {
                    index++;
                }
                // Now check the type of array
                c = descriptor.charAt(index);
                if (c == 'L') {
                    // Object reference in array
                    while (descriptor.charAt(index) != ';') {
                        index++;
                    }
                    index++; // Move past the ';'
                } else {
                    index++; // Primitive type in array
                }
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }
    // Now index is at the ')', we can process the return type if needed, but for this method, we stop here
}

