public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }

    String normalizedPath = normalizePath(path);
    String normalizedRelativePath = normalizePath(relativePath);

    if (normalizedRelativePath.startsWith("/")) {
        return normalizedRelativePath;
    }

    String[] pathParts = normalizedPath.split("/");
    String[] relativePathParts = normalizedRelativePath.split("/");

    int i = 0;
    for (String part : relativePathParts) {
        if (part.equals("..")) {
            if (pathParts.length > 1) {
                pathParts = Arrays.copyOf(pathParts, pathParts.length - 1);
            }
        } else if (!part.equals(".")) {
            pathParts = Arrays.copyOf(pathParts, pathParts.length + 1);
            pathParts[pathParts.length - 1] = part;
        }
    }

    return String.join("/", pathParts);
}

